// match() only sizes maps for ordinally paired workloads. Scene
// matching may consider any scene pair, including an unmatched one.
if (!firstCurWorkloadMap.mapped ||
    firstCurWorkloadMap.prevWorkloadIndex != firstPrevProjIndices.workloadIndex) return;

// Calls with the same hash often repeat one kind of matching input
// while using distinct inputs for another. Deduplicate each domain
// independently, then insert the same numeric IndexPair union as the
// original full call cross-product.
using TransformWork = std::array<uint32_t, 3>;
using TileWork = std::array<uint32_t, 4>;
using LookAtWork = std::array<uint32_t, 2>;
thread_local std::vector<TransformWork> curTransformWork;
thread_local std::vector<TransformWork> prevTransformWork;
thread_local std::vector<TileWork> curTileWork;
thread_local std::vector<TileWork> prevTileWork;
thread_local std::vector<LookAtWork> curLookAtWork;
thread_local std::vector<LookAtWork> prevLookAtWork;
thread_local std::vector<uint32_t> curLookAtIndices;
thread_local std::vector<uint32_t> prevLookAtIndices;

auto sortUnique = [](auto &values) {
    std::sort(values.begin(), values.end());
    values.erase(std::unique(values.begin(), values.end()), values.end());
};

auto collectUniqueWork = [&](auto first, auto last, const GameScene &scene,
    std::vector<TransformWork> &transformWork, std::vector<TileWork> &tileWork,
    std::vector<LookAtWork> &lookAtWork) {
    transformWork.clear();
    tileWork.clear();
    lookAtWork.clear();
    for (auto it = first; it != last; ++it) {
        const GameCallMap callMap = it->second;
        const GameIndices::Projection &projIndices = scene.projections[callMap.sceneProjIndex];
        const Workload &workload = workloadQueue.workloads[projIndices.workloadIndex];
        const FramebufferPair &fbPair = workload.fbPairs[projIndices.fbPairIndex];
        const Projection &proj = fbPair.projections[projIndices.projectionIndex];
        const GameCall &call = proj.gameCalls[callMap.callIndex];
        if (callMap.doTransformMatching) {
            transformWork.emplace_back(TransformWork{
                callMap.sceneProjIndex, call.callDesc.minWorldMatrix, call.callDesc.maxWorldMatrix});
        }
        if (callMap.doTileInterpolation) {
            tileWork.emplace_back(TileWork{
                callMap.sceneProjIndex, call.callDesc.tileIndex, call.callDesc.tileCount,
                callMap.doTileMatching});
        }
        const uint32_t textureGenMask = G_LIGHTING | G_TEXTURE_GEN;
        if ((call.callDesc.geometryMode & textureGenMask) == textureGenMask) {
            lookAtWork.emplace_back(LookAtWork{
                callMap.sceneProjIndex, call.meshDesc.faceIndicesStart});
        }
    }
    sortUnique(transformWork);
    sortUnique(tileWork);
    sortUnique(lookAtWork);
};

auto projectionWorkload = [&](const GameScene &scene, uint32_t sceneProjIndex) -> const Workload & {
    const GameIndices::Projection &indices = scene.projections[sceneProjIndex];
    return workloadQueue.workloads[indices.workloadIndex];
};

// Traverse one hash bucket at a time. Hash collisions stay in the same
// bucket, as in the pinned implementation. Thread-local vectors retain
// capacity, and domains with no eligible work do no pair traversal.
for (auto curBucket = curCallHashMap.cbegin(); curBucket != curCallHashMap.cend();) {
    const auto curRange = curCallHashMap.equal_range(curBucket->first);
    const auto prevRange = prevCallHashMap.equal_range(curBucket->first);
    if (prevRange.first == prevRange.second) {
        curBucket = curRange.second;
        continue;
    }
    collectUniqueWork(curRange.first, curRange.second, curScene,
        curTransformWork, curTileWork, curLookAtWork);
    collectUniqueWork(prevRange.first, prevRange.second, prevScene,
        prevTransformWork, prevTileWork, prevLookAtWork);

    for (const TransformWork &cur : curTransformWork) {
        for (const TransformWork &prev : prevTransformWork) {
            // This matcher stores results in the first workload's map.
            // Never interpret another workload's matrix indices there.
            if (curScene.projections[cur[0]].workloadIndex != firstCurProjIndices.workloadIndex ||
                prevScene.projections[prev[0]].workloadIndex != firstPrevProjIndices.workloadIndex) {
                continue;
            }
            const uint32_t curWorldMatrixCount = (cur[2] - cur[1]) + 1;
            const uint32_t prevWorldMatrixCount = (prev[2] - prev[1]) + 1;
            if (curWorldMatrixCount != prevWorldMatrixCount) {
                continue;
            }
            const Workload &curWorkload = projectionWorkload(curScene, cur[0]);
            const Workload &prevWorkload = projectionWorkload(prevScene, prev[0]);
            for (uint32_t w = 0; w < curWorldMatrixCount; w++) {
                const uint32_t curWorldMatrix = cur[1] + w;
                const uint32_t curGroupIndex = curWorkload.drawData.worldTransformGroups[curWorldMatrix];
                const TransformGroup &curGroup = curWorkload.drawData.transformGroups[curGroupIndex];
                const uint32_t prevWorldMatrix = prev[1] + w;
                const uint32_t prevGroupIndex = prevWorkload.drawData.worldTransformGroups[prevWorldMatrix];
                const TransformGroup &prevGroup = prevWorkload.drawData.transformGroups[prevGroupIndex];
                if ((curGroup.matrixId == prevGroup.matrixId) && ((curGroup.matrixId == G_EX_ID_AUTO) || ((curGroup.matrixId != G_EX_ID_IGNORE) && (curGroup.ordering == G_EX_ORDER_AUTO)))) {
                    transformCheckSet.emplace(curWorldMatrix, prevWorldMatrix);
                }
            }
        }
    }

    for (const TileWork &cur : curTileWork) {
        for (const TileWork &prev : prevTileWork) {
            if (curScene.projections[cur[0]].workloadIndex != firstCurProjIndices.workloadIndex ||
                prevScene.projections[prev[0]].workloadIndex != firstPrevProjIndices.workloadIndex) continue;
            if (cur[2] != prev[2]) {
                continue;
            }
            const Workload &curWorkload = projectionWorkload(curScene, cur[0]);
            const Workload &prevWorkload = projectionWorkload(prevScene, prev[0]);
            for (uint32_t t = 0; t < cur[2]; t++) {
                const DrawCallTile &curCallTile = curWorkload.drawData.callTiles[cur[1] + t];
                const DrawCallTile &prevCallTile = prevWorkload.drawData.callTiles[prev[1] + t];
                const bool doTileMatching = cur[3] && prev[3];
                if (doTileMatching && (curCallTile.tmemHashOrID != prevCallTile.tmemHashOrID)) {
                    continue;
                }
                tileCheckSet.emplace(cur[1] + t, prev[1] + t);
            }
        }
    }

    if (!curLookAtWork.empty() && !prevLookAtWork.empty()) {
        auto resolveLookAtIndices = [&](const std::vector<LookAtWork> &work,
            const GameScene &scene, uint32_t expectedWorkloadIndex,
            std::vector<uint32_t> &indices) {
            indices.clear();
            for (const LookAtWork &item : work) {
                if (scene.projections[item[0]].workloadIndex != expectedWorkloadIndex) continue;
                const Workload &workload = projectionWorkload(scene, item[0]);
                const uint32_t vertexIndex = workload.drawData.faceIndices[item[1]];
                const uint32_t lookAtIndex = workload.drawData.lookAtIndices[vertexIndex] >> RSP_LOOKAT_INDEX_SHIFT;
                indices.emplace_back(lookAtIndex);
            }
            sortUnique(indices);
        };
        resolveLookAtIndices(curLookAtWork, curScene, firstCurProjIndices.workloadIndex, curLookAtIndices);
        resolveLookAtIndices(prevLookAtWork, prevScene, firstPrevProjIndices.workloadIndex, prevLookAtIndices);
        for (uint32_t curLookAtIndex : curLookAtIndices) {
            for (uint32_t prevLookAtIndex : prevLookAtIndices) {
                lookAtCheckSet.emplace(curLookAtIndex, prevLookAtIndex);
            }
        }
    }

    curBucket = curRange.second;
}

const RigidBody *prevRigidBody;
const hlslpp::float4x4 &firstCurViewProj = firstCurWorkload.drawData.viewProjTransforms[firstCurProj.transformsIndex];
const hlslpp::float4x4 &firstPrevViewProj = firstPrevWorkload.drawData.viewProjTransforms[firstPrevProj.transformsIndex];
// AUTO matrix IDs identify no particular model part. For geometry
// whose vertices are not interpolated, admit a previous matrix only
// when its local vertex sequence is exactly the same.
thread_local std::vector<uint64_t> curGeometryHashes;
thread_local std::vector<uint64_t> prevGeometryHashes;
thread_local std::vector<uint8_t> curGeometryHashed;
thread_local std::vector<uint8_t> prevGeometryHashed;
curGeometryHashes.resize(firstCurWorkload.drawData.worldTransforms.size());
prevGeometryHashes.resize(firstPrevWorkload.drawData.worldTransforms.size());
curGeometryHashed.assign(curGeometryHashes.size(), 0);
prevGeometryHashed.assign(prevGeometryHashes.size(), 0);
auto geometryHash = [](const DrawData &data, uint32_t index,
    std::vector<uint64_t> &hashes, std::vector<uint8_t> &hashed, uint64_t &result) {
    const uint32_t first = data.worldTransformVertexIndices[index];
    const uint32_t count = data.worldTransformVertexCount(index);
    const size_t available = data.posFloats.size() / 3;
    if (count == 0 || first > available || count > available - first) return false;
    if (!hashed[index]) {
        hashes[index] = XXH3_64bits(data.posFloats.data() + size_t(first) * 3,
            size_t(count) * 3 * sizeof(float));
        hashed[index] = 1;
    }
    result = hashes[index];
    return true;
};
for (const IndexPair &indices : transformCheckSet) {
    const uint32_t curGroupIndex = firstCurWorkload.drawData.worldTransformGroups[indices.first];
    const TransformGroup &curGroup = firstCurWorkload.drawData.transformGroups[curGroupIndex];
    if (curGroup.matrixId == G_EX_ID_AUTO &&
        curGroup.vertexInterpolation == G_EX_COMPONENT_SKIP) {
        const DrawData &curData = firstCurWorkload.drawData;
        const DrawData &prevData = firstPrevWorkload.drawData;
        if (curData.worldTransformVertexCount(indices.first) !=
            prevData.worldTransformVertexCount(indices.second)) continue;
        uint64_t curHash = 0;
        uint64_t prevHash = 0;
        if (!geometryHash(curData, indices.first, curGeometryHashes, curGeometryHashed, curHash) ||
            !geometryHash(prevData, indices.second, prevGeometryHashes, prevGeometryHashed, prevHash) ||
            curHash != prevHash) continue;
    }
    const hlslpp::float4x4 &curTransform = firstCurWorkload.drawData.worldTransforms[indices.first];
    const hlslpp::float4x4 &prevTransform = firstPrevWorkload.drawData.worldTransforms[indices.second];
    const uint32_t prevGroupIndex = firstPrevWorkload.drawData.worldTransformGroups[indices.second];
    const TransformGroup &prevGroup = firstPrevWorkload.drawData.transformGroups[prevGroupIndex];
    const bool autoSkipQuad = tooie::rt64_match::guard_auto_skip_quad(
        curGroup.matrixId == G_EX_ID_AUTO && prevGroup.matrixId == G_EX_ID_AUTO,
        curGroup.vertexInterpolation == G_EX_COMPONENT_SKIP &&
            prevGroup.vertexInterpolation == G_EX_COMPONENT_SKIP,
        firstCurWorkload.drawData.worldTransformVertexCount(indices.first),
        firstPrevWorkload.drawData.worldTransformVertexCount(indices.second));
    if (!tooie::rt64_match::allow_world_pair(autoSkipQuad,
            curTransform[3][0], curTransform[3][1], curTransform[3][2],
            prevTransform[3][0], prevTransform[3][1], prevTransform[3][2])) continue;
    prevRigidBody = (firstPrevWorkloadMap != nullptr) ? &firstPrevWorkloadMap->transforms[indices.second].rigidBody : nullptr;

    TransformMatchResult matchResult = computeTransformMatch(curTransform, firstCurViewProj, prevTransform, firstPrevViewProj, prevRigidBody);
    if (matchResult.valid) {
        matchCandidates.emplace_back(indices.first, indices.second, matchResult.computeDifference());
    }
}
